package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Comment;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Node_siblingNodes_TriageGen0Test {

    @Test
    public void test_siblingNodes_NoParent_ReturnsEmptyList() {
        // Arrange
        Node node = new Node("");

        // Act
        List<Node> siblings = node.siblingNodes();

        // Assert
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void test_siblingNodes_SiblingNode_ReturnsSiblingNode() {
        // Arrange
        Node parent = new Node("");
        Node sibling = new Node("");
        parent.appendChild(sibling);

        // Act
        List<Node> siblings = parent.siblingNodes();

        // Assert
        assertEquals(Arrays.asList(sibling), siblings);
    }

    @Test
    public void test_siblingNodes_MultipleSiblingNodes_ReturnsAllSiblingNodes() {
        // Arrange
        Node parent = new Node("");
        Node sibling1 = new Node("");
        Node sibling2 = new Node("");
        parent.appendChild(sibling1).appendChild(sibling2);

        // Act
        List<Node> siblings = parent.siblingNodes();

        // Assert
        assertEquals(Arrays.asList(sibling1, sibling2), siblings);
    }

    @Test
    public void test_siblingNodes_NodeWithChildren_ReturnsChildrenAsSiblingNodes() {
        // Arrange
        Node parent = new Node("");
        Node child = new Node("");
        parent.appendChild(child);

        // Act
        List<Node> siblings = parent.siblingNodes();

        // Assert
        assertEquals(Arrays.asList(child), siblings);
    }

    @Test
    public void test_siblingNodes_NullParent_ReturnsEmptyList() {
        // Arrange
        Node node = new Node("");

        // Act
        List<Node> siblings = node.siblingNodes();

        // Assert
        assertTrue(siblings.isEmpty());
    }
}
